 6	/* Initialize onboard LEDs: PG6 (LED1), PD4 (LED2), PD5 (LED3), PK3 (LED4) */
 7	static void prvSetupHardware(void)
 8	{
 9	    /* Enable GPIO clocks */
10	    RCC->AHB1ENR |= RCC_AHB1ENR_GPIODEN | RCC_AHB1ENR_GPIOGEN | RCC_AHB1ENR_GPIOKEN;
11	
12	    /* Configure PG6 as General purpose output mode (01) */
13	    GPIOG->MODER &= ~(3UL << (LED1_PIN * 2));
14	    GPIOG->MODER |= (1UL << (LED1_PIN * 2));
15	    /* LEDs are active LOW: turn off initially by setting bit in BSRR */
16	    GPIOG->BSRR = (1UL << LED1_PIN);
17	
18	    /* Configure PD4 and PD5 as General purpose output mode (01) */
19	    GPIOD->MODER &= ~((3UL << (LED2_PIN * 2)) | (3UL << (LED3_PIN * 2)));
20	    GPIOD->MODER |= ((1UL << (LED2_PIN * 2)) | (1UL << (LED3_PIN * 2)));
21	    GPIOD->BSRR = (1UL << LED2_PIN) | (1UL << LED3_PIN);
22	
23	    /* Configure PK3 as General purpose output mode (01) */
24	    GPIOK->MODER &= ~(3UL << (LED4_PIN * 2));
25	    GPIOK->MODER |= (1UL << (LED4_PIN * 2));
26	    GPIOK->BSRR = (1UL << LED4_PIN);
27	}
28	
29	/* LED Blink Task: Toggles LED1 (PG6) every 500 ms */
30	static void vBlinkTask(void *pvParameters)
31	{
32	    (void)pvParameters;
33	    for (;;) {
34	        /* Turn ON LED1 (Active LOW: reset pin via high half of BSRR) */
35	        GPIOG->BSRR = (1UL << (LED1_PIN + 16));
36	        vTaskDelay(pdMS_TO_TICKS(500));
37	
38	        /* Turn OFF LED1 (set pin via low half of BSRR) */
39	        GPIOG->BSRR = (1UL << LED1_PIN);
40	        vTaskDelay(pdMS_TO_TICKS(500));
41	    }
42	}
43	
44	int main(void)
45	{
46	    prvSetupHardware();
47	
48	    /* Create the LED blink task */
49	    xTaskCreate(
50	        vBlinkTask,
51	        "Blink",
52	        configMINIMAL_STACK_SIZE,
53	        0,
54	        tskIDLE_PRIORITY + 1,
55	        0
56	    );
57	
58	    /* Start the scheduler */
59	    vTaskStartScheduler();
60	
61	    /* Should never reach here */
62	    for (;;);
63	    return 0;
64	}

